(function(){
function bodyOf(x){var b='';try{b=String(x.body())}catch(e){try{b=String(x.body)}catch(e2){b=''}}return b;}
var b=bodyOf(result);
if(b.indexOf('alert(')>=0&&b.length<500){
  var msg='';
  var m=String(b).match(/alert\("([^"]+)"\)/);
  if(m)msg=m[1];
  var tip='';
  if(msg.indexOf('搜索间隔')>=0){
    tip='<html><body><p>站点搜索限频：'+msg+'。书源每次搜索前会自动清除限频标记，若仍遇此提示请等待2分钟或稍后再试。</p></body></html>';
  }else if(msg.indexOf('关键字')>=0){
    tip='<html><body><p>关键词不符合要求：'+msg+'。本站要求关键词至少 4 个汉字，请输入更长的书名或作者名。</p></body></html>';
  }else{
    tip='<html><body><p>站点提示：'+msg+'</p></body></html>';
  }
  try{
    return new Packages.io.legado.app.help.http.StrResponse(String(baseUrl), tip);
  }catch(e){return result;}
}
return result;
})()

loginUrl:
function login(){java.toast('本站无需账号登录；请用下方按钮管理线路')}
function SJ_hosts(){return ['https://wap.shoujixs.net','https://open-ki.jishouzj.cc','https://open-ki.jishouxs.cc'];}
function SJ_host(sv){
  var h='';try{h=String(sv.getVariable()||'')}catch(e){h=''}
  var hs=SJ_hosts();
  for(var i=0;i<hs.length;i++){if(h==hs[i])return hs[i];}
  if(h.indexOf('http')===0)return h;
  return String(sv.getKey());
}
function SJ_set(sv,u){try{sv.setVariable(u)}catch(e){}return u;}
function SJ_refresh(){
  var ok=false;
  try{java.reLoginView();ok=true}catch(e){}
  if(!ok){try{java.reUiView();ok=true}catch(e){}}
  return ok;
}
function FQ_sj_now(jv,sv){
  var h=SJ_host(sv);
  java.toast('🌐 当前线路：'+h+'（书架旧书仍走其入库时的域名）');
}
function FQ_sj_pick(jv,sv,idx){
  var hs=SJ_hosts();
  if(idx<0||idx>=hs.length){java.toast('❌ 线路编号错误');return;}
  java.toast('⏳ 正在切换到线路'+(idx+1)+'…');
  SJ_set(sv,hs[idx]);
  java.toast('✅ 已切换：'+hs[idx]+'（可搜索一次验证连通性）');
  SJ_refresh();
}
function SJ_speedAll(jv){
  var hs=SJ_hosts();
  var urls=[];for(var i=0;i<hs.length;i++)urls.push(hs[i]+'/');
  var rs=null;
  try{rs=jv.ajaxAll(urls);}catch(e){return null;}
  var best=-1;var bestT=9007199254740992;var msg=[];
  for(var i=0;i<hs.length;i++){
    var t=-1;var alive=false;
    try{
      var r=rs[i];var b='';
      try{b=String(r.body())}catch(e1){b=''}
      if(b.length>5000){
        alive=true;
        try{t=Number(r.callTime())}catch(e2){t=-1}
      }
    }catch(e){alive=false;}
    var label=alive?(t>=0?(t+'ms'):'在线'):'失效';
    try{jv.put('sjMs'+i,label)}catch(e3){}
    msg.push(hs[i].replace('https://','')+'='+(alive?(t>=0?(t+'ms'):'在线'):'失效'));
    if(alive&&t>=0&&t<bestT){bestT=t;best=i;}
  }
  return {best:best,bestT:bestT,msg:msg.join(' ｜ ')};
}
function FQ_sj_speed(jv,sv){
  java.toast('⏳ 正在并发测速 3 条线路（约2~8秒）…');
  var r=SJ_speedAll(jv);
  if(r==null){java.toast('❌ 测速执行失败（ajaxAll 异常）');SJ_refresh();return;}
  java.toast('⏱ 测速完成：'+r.msg);
  SJ_refresh();
}
function FQ_sj_auto(jv,sv){
  java.toast('⏳ 正在测速并自动切换最快线路…');
  var r=SJ_speedAll(jv);
  if(r==null){java.toast('❌ 测速执行失败（ajaxAll 异常）');SJ_refresh();return;}
  if(r.best<0){
    java.toast('❌ 全部线路异常，请检查网络后重试：'+r.msg);
    SJ_refresh();return;
  }
  var hs=SJ_hosts();
  SJ_set(sv,hs[r.best]);
  java.toast('✅ 已切换最快线路：'+hs[r.best]+'（'+r.bestT+'ms）｜'+r.msg);
  SJ_refresh();
}
function FQ_sj_custom(jv,sv){
  var v='';
  try{v=String(result.get('customUrl')||'')}catch(e){}
  if(!v||v=='null'){try{v=String(result['customUrl']||'')}catch(e){v=''}}
  if(!v||v.indexOf('http')!==0){
    java.toast('❌ 请先在输入框输入以 http 开头的完整网址（如 https://wap.shoujixs.net）');
    return;
  }
  v=v.replace(/\/+$/,'');
  java.toast('⏳ 正在切换自定义网址…');
  SJ_set(sv,v);
  java.toast('✅ 已切换：'+v+'（该站系列域名共用同一书库；若是陌生镜像请先搜索验证）');
  SJ_refresh();
}
function FQ_sj_clear(jv,sv){
  var n=0;
  try{cookie.removeCookie('https://wap.shoujixs.net/');n++;}catch(e){}
  try{cookie.removeCookie('https://wap.shoujixs.net/search/');n++;}catch(e){}
  var hs=SJ_hosts();
  for(var i=0;i<hs.length;i++){try{cookie.removeCookie(hs[i]+'/')}catch(e){}}
  java.toast('🧹 已清除本站全部Cookie（含限频标记ss_search_delay），现在可以搜索了');
  SJ_refresh();
}
function FQ_sj_check(jv,sv){
  var h=SJ_host(sv);
  java.toast('⏳ 正在检测 '+h+' …');
  var t0=Date.now();var b='';
  try{b=String(jv.ajax(h+'/'))}catch(e){
    java.toast('❌ 连接失败：'+e+'（请换线路）');
    return;
  }
  var ms=Date.now()-t0;
  if(b.length>5000){
    java.toast('✅ 连接正常 '+ms+'ms ｜ 本站无需账号登录 ｜ 当前线路：'+h);
  }else{
    java.toast('⚠️ 响应异常（仅'+b.length+'字符），域名可能已失效，请切换线路');
  }
}

