});

var tags = org.jsoup.Jsoup.parse(java.ajax(source.key + "/category/"))
    .select('.CGsectionTwo-left a')
    .toArray()
    .map(tag => {
        let text = [String(tag.text()).trim(), String(tag.attr('href')).match(/(\d+)/)[1]];
        return String(tag.text()).trim() ? text :  null;
    })
    .filter(item => item !== null);

[
    ["༺ˇ»`ʚ  分类  ɞ´«ˇ༻", "/category/"],
    ["༺ˇ»`ʚ  排行榜  ɞ´«ˇ༻", null],
    ["༺ˇ»`ʚ  总榜  ɞ´«ˇ༻", "/rank/all/"],
    ["༺ˇ»`ʚ  周榜  ɞ´«ˇ༻", "/rank/"],
    ["༺ˇ»`ʚ  月榜  ɞ´«ˇ༻", "/rank/month/"],
    ["༺ˇ»`ʚ  全本  ɞ´«ˇ༻", "/category/finish/"]
].forEach(item => {
    push(item[0], null, 1);
    if (item[1]) {
        tags.forEach((tag, index) => {
            let url = item[1] + tag[1] + "/{{page}}.html";
            push(tag[0], url, (index ? 0.2 : 1));
        });
    }
});
JSON.stringify(result);

jsLib:
function decrypt(encryptedTxt, keySeed) {
    const { java } = this;
    let result;
    try {
        const fullKey = java.md5Encode(keySeed);
        const ivBytes = java.strToBytes(fullKey.substring(0, 16));
        const keyBytes = java.strToBytes(fullKey.substring(16));

        const Cipher = java.createSymmetricCrypto(
            "AES/CBC/Pkcs7Padding",
            keyBytes,
            ivBytes
        );

        result = Cipher.decryptStr(java.base64DecodeToByteArray(encryptedTxt));
    } catch (e) {
        java.log(e.message);
        result = "解密失败";
    }
    return result;
}

ruleToc.chapterList:
ol > li
<js>
let Regex_ = /(data-[a-zA-Z0-9]+)/g;
let label = result.select('li')[0].outerHtml().match(Regex_)[1];
result.sort((a, b) => +a.attr(label) - +b.attr(label));
chapterList = result.select('a').toArray().map(e => {
    let labeln = e.outerHtml().match(Regex_);
    return {
        title: String(e.attr(labeln[0])).trim() || e.text(),
        url: java.base64Decode(String(e.attr(labeln[1])))
    }
});
JSON.stringify(chapterList);
</js>
$[*]

