@js:
(function () {
  var meta = sqGetChapterMeta.call(this, baseUrl);
  if (!meta || !meta.bookId || !meta.chapterId) return "获取正文失败：缺少书籍或章节编号，请刷新目录";
  // 使用当前章节地址携带的目录标记，避免跨书缓存覆盖后误判。
  var freeMatch = String(baseUrl || "").match(/[#&?]sqFree=([01])(?:[&#]|$)/);
  var isFree = freeMatch ? freeMatch[1] === "1" : null;
  if (isFree === null) {
    try {
      var vip = chapter.isVip;
      if (vip !== null && vip !== undefined) {
        isFree = !/^(true|1)$/i.test(String(vip));
      }
    } catch (eVip) {}
  }
  if (isFree === null) return "获取正文失败：缺少章节免费标记，请刷新目录";
  var text = "";
  if (isFree) {
    // 沿用同人源的官方正文格式与解码方式。
    var raw = String(src || "").trim();
    if (!raw) return "获取免费正文失败：官方响应为空";
    if (/^data:text\/plain;base64,/i.test(raw)) {
      try {
        var dataMatch = raw.match(/^data:text\/plain;base64,([^#,\s]+)/i);
        if (dataMatch && dataMatch[1]) raw = String(java.base64Decode(dataMatch[1]) || "").trim();
      } catch (eDataUrl) { return "获取免费正文失败：data URL 解码失败"; }
    }
    if (/^https?:\/\//i.test(raw)) {
      try { raw = String(java.ajax(raw) || ""); }
      catch (eRequest) { return "获取免费正文失败：官方章节请求失败"; }
    }
    var obj;
    try { obj = JSON.parse(raw || "{}"); }
    catch (eParse) { return "获取免费正文失败：官方响应格式错误"; }
    if (obj.message != "success" || !obj.ChapterContent) {
      return "获取免费正文失败：" + String(obj.message || "官方未返回正文") + "，如章节状态有变化请刷新目录";
    }
    function decodeContent(value) {
      return String(value || "").split("").map(function (ch) {
        if (!/[A-Za-z]/.test(ch)) return ch;
        var c = Math.floor(ch.charCodeAt(0) / 97);
        var k = (ch.toLowerCase().charCodeAt(0) - 83) % 26 || 26;
        return String.fromCharCode(k + (c === 0 ? 64 : 96));
      }).join("");
    }
    try { text = String(java.base64Decode(decodeContent(obj.ChapterContent)) || ""); }
    catch (eDecode) { return "获取免费正文失败：正文解码失败"; }
    if (!text) return "获取免费正文失败：章节内容为空";
  } else {
    // 上锁章节继续使用知秋源现有服务器、登录信息和 API Key。
    var response = sqPost.call(this, "/v1/reader/chapter-content", {
      bookId: String(meta.bookId),
      chapterId: String(meta.chapterId)
    });
    if (!response || !response.ok) return "获取正文失败：" + String(response && response.error || "接口请求失败");
    var data = response.data || {};
    text = data.content;
    if (typeof text !== "string" || !text) return "获取正文失败：接口未返回章节正文";
  }
  var chapterQuote = "";
  try { if (typeof chapter !== "undefined" && chapter) chapterQuote = String(chapter.title || chapter.chapterName || ""); } catch (eChapterQuote) {}
  return sqDecorateContent.call(this, text, meta.bookId, meta.chapterId, chapterQuote);
})();

