function SQ_cdnParse(body){
 var s=SQ_S(body),i=s.indexOf("("),j=s.lastIndexOf(")"),inner=i>0&&j>i?s.slice(i+1,j):s;
 try{var a=JSON.parse(inner);var c=SQ_S(a&&a[0]&&a[0].content);
  if(!c)return "";
  return SQ_trim(c.replace(/<br\s*\/?>/gi,"\n").replace(/&nbsp;/g," ").replace(/<[^>]*>/g,"")
   .replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"'));
 }catch(e){return "";}
}
function SQ_rot13(s){return SQ_S(s).replace(/[a-zA-Z]/g,function(c){var b=c<="Z"?65:97;return String.fromCharCode((c.charCodeAt(0)-b+13)%26+b);});}
function SQ_ciDecode(s){var r=SQ_rot13(s).replace(/\s+/g,"");
 try{return SQ_u8s(SQ_b64d(r)).replace(/<br\s*\/?>/gi,"\n");}catch(e){return "";}}
function SQ_content(Jv,S,rawUrl){
 var bid=SQ_bid(rawUrl),cid=SQ_cid(rawUrl);
 if(!bid||!cid)throw new Error("书旗：章节地址无效");
 var note=[],i,f,h,sch,url,txt;
 var pref=SQ_cdnHost(S).split("//")[1];
 var hs=SQ_CDN_HOSTS.slice();
 hs.sort(function(a,b){return (a===pref?-1:0)-(b===pref?-1:0)});
 for(sch=0;sch<2;sch++){
  var scheme=sch===0?"https":"http";
  for(h=0;h<hs.length;h++){
   for(f=0;f<SQ_CDN_FLAGS.length;f++){
    url=scheme+"://"+hs[h]+"/httpserver/filecache/get_book_content_"+bid+"_"+cid+"_"+SQ_CDN_FLAGS[f]+"_0_0.html";
    try{var b=SQ_webGet(Jv,url);txt=SQ_cdnParse(b);
     if(txt.length>30)return txt;note.push(SQ_CDN_HOSTS[h]+"/"+SQ_CDN_FLAGS[f]+":空");
    }catch(e){note.push(SQ_CDN_HOSTS[h]+"/"+SQ_CDN_FLAGS[f]+":失败");}
   }
  }
 }
 try{var cr=SQ_api(Jv,S,SQ_P_CHINFO,[["bookId",bid],["chapterId",cid]],SQ_CIUID);
  var enc=SQ_S(cr&&cr.data&&cr.data.chapter&&cr.data.chapter.content);
  if(enc){var dec=SQ_ciDecode(enc);if(dec.length>30)return dec;}
 }catch(e){note.push("chapterinfo:"+SQ_S(e).slice(0,40));}
 throw new Error("书旗：本章正文不可用（"+(cid)+"）。"+(note.length?note.slice(0,3).join("; "):"可能需登录或为付费章"));
