 var path="",m;
 if((m=u.match(/[?&]rank=([A-Za-z]+)/)))path="/ranklist?rank="+m[1]+"&page="+p;
 else if(/[?&](?:sz|fc|wd|tm|st|store|sqs)=/.test(u)||u.indexOf("/store")>=0){
  var q=u.indexOf("?")>=0?u.slice(u.indexOf("?")+1).replace(/&amp;/g,"&"):"";
  q=q.replace(/[?&]?page=[0-9]+/g,"").replace(/^&+|&+$/g,"");
  var keep=[],kv=q.split("&"),i0;
  for(i0=0;i0<kv.length;i0++){if(/^(sz|fc|wd|tm|st)=/.test(kv[i0]))keep.push(kv[i0]);}
  path="/store?"+(keep.length?keep.join("&")+"&":"")+"page="+p;
 }
 else path="/rank?page="+p;
 var web=SQ_web(S);
 var h="";
 try{h=SQ_webGet(Jv,web+path);}catch(e){}
 if(h.length<2000)return [];
 var out=[],seen={},re,i2;
 if(path.indexOf("/ranklist")===0||path.indexOf("/rank?")===0){
  re=/<li class="clearfix">([\s\S]*?)<\/li>/g;
  var mm;
