   var tags=(li.match(/class="ranklist-tag">([\s\S]*?)<\/p>/)||[])[1]||"";
   var tg=SQ_plain(tags.replace(/<[^>]*>/g," "));
   out.push({name:SQ_plain(title),author:SQ_plain(au),bookUrl:SQ_bookUrl(mb[1],S),
    coverUrl:SQ_S(img),intro:SQ_plain(des),kind:[SQ_plain(cate),tg].filter(function(x){return x}).join(",")});
  }
 }else{
  var lis=h.split('<li');
  for(i2=1;i2<lis.length;i2++){
   var li=SQ_S(lis[i2].split('</li>')[0]);
   if(li.indexOf('store-tag')<0)continue;
   var mb2=li.match(/\/book\/(\d+)\.html/);if(!mb2||seen[mb2[1]])continue;seen[mb2[1]]=1;
   var nm=(li.match(/<h3[^>]*>([\s\S]*?)<\/h3>/)||[])[1]||'';
   if(!nm){var mt2=li.match(/<a[^>]*href="\/book\/\d+\.html"[^>]*title="([^"]*)"/);if(mt2)nm=mt2[1];}
   var im=(li.match(/<img[^>]*class="cover"[^>]*src="([^"]+)"/)||li.match(/<img[^>]*src="([^"]+)"/)||[])[1]||'';
   var des=(li.match(/class="store-des">([\s\S]*?)<\/p>/)||[])[1]||'';
   var au=(li.match(/class="store-tag[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/)||[])[1]||'';
   au=SQ_plain(au).replace(/^作者[：:]\s*/,'');
   var cate=(li.match(/class="store-tag[^>]*>[\s\S]*?<span>([\s\S]*?)<\/span>/)||[])[1]||'';
   if(!nm)continue;
   out.push({name:SQ_plain(nm),author:au,bookUrl:SQ_bookUrl(mb2[1],S),coverUrl:SQ_S(im),
    intro:SQ_plain(des),kind:SQ_plain(cate)});
  }
 }
 return out;
}
